// Package workspace renders guarded native Go and editor workspaces.
package workspace

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/spice-framework/development/internal/catalog"
)

const (
	goWorkName   = "go.work"
	editorName   = "spice.code-workspace"
	goWorkMarker = "// Code generated by spice-dev workspace. DO NOT EDIT."
)

var (
	ErrStale   = errors.New("generated workspace is stale")
	ErrUnowned = errors.New("workspace file is not owned by spice-dev")
)

type Plan struct {
	GoWork []byte
	Editor []byte
}

type editorWorkspace struct {
	SpiceGenerated bool           `json:"spiceGenerated"`
	Folders        []editorFolder `json:"folders"`
}

type editorFolder struct {
	Name string `json:"name"`
	Path string `json:"path"`
}

func Render(root string, value catalog.Catalog) (Plan, error) {
	if err := value.Validate(); err != nil {
		return Plan{}, err
	}
	absolute, err := requireRoot(root)
	if err != nil {
		return Plan{}, err
	}
	var modules []string
	folders := make([]editorFolder, 0, len(value.Active()))
	for _, repository := range value.Active() {
		directory := filepath.Join(absolute, repository.Directory)
		info, statErr := os.Lstat(directory)
		if errors.Is(statErr, os.ErrNotExist) {
			continue
		}
		if statErr != nil {
			return Plan{}, fmt.Errorf("inspect workspace repository %s: %w", repository.Name, statErr)
		}
		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
			return Plan{}, fmt.Errorf("workspace repository %s is not a real directory", repository.Name)
		}
		folders = append(folders, editorFolder{
			Name: repository.Name,
			Path: filepath.ToSlash(repository.Directory),
		})
		if repository.Artifact != "go-module" {
			continue
		}
		modulePath, moduleErr := readModulePath(filepath.Join(directory, "go.mod"))
		if moduleErr != nil {
			return Plan{}, fmt.Errorf("inspect workspace module %s: %w", repository.Name, moduleErr)
		}
		if modulePath != repository.Module {
			return Plan{}, fmt.Errorf(
				"workspace repository %s declares module %q, catalog expects %q",
				repository.Name,
				modulePath,
				repository.Module,
			)
		}
		modules = append(modules, "\t./"+filepath.ToSlash(repository.Directory))
	}
	if len(folders) == 0 {
		return Plan{}, errors.New("workspace has no active repository checkouts")
	}
	goWork := goWorkMarker + "\n\n" +
		"go 1.26.0\n\n" +
		"toolchain go1.26.5\n"
	if len(modules) != 0 {
		goWork += "\nuse (\n" + strings.Join(modules, "\n") + "\n)\n"
	}
	editor, err := json.MarshalIndent(editorWorkspace{
		SpiceGenerated: true,
		Folders:        folders,
	}, "", "  ")
	if err != nil {
		return Plan{}, fmt.Errorf("render editor workspace: %w", err)
	}
	editor = append(editor, '\n')
	return Plan{GoWork: []byte(goWork), Editor: editor}, nil
}

func Apply(root string, plan Plan, check bool) error {
	absolute, err := requireRoot(root)
	if err != nil {
		return err
	}
	files := []struct {
		name    string
		content []byte
		owned   func([]byte) bool
	}{
		{name: goWorkName, content: plan.GoWork, owned: ownsGoWork},
		{name: editorName, content: plan.Editor, owned: ownsEditor},
	}
	for _, file := range files {
		if err := applyFile(absolute, file.name, file.content, file.owned, check); err != nil {
			return err
		}
	}
	return nil
}

func requireRoot(root string) (string, error) {
	if strings.TrimSpace(root) == "" {
		return "", errors.New("workspace root is required")
	}
	absolute, err := filepath.Abs(root)
	if err != nil {
		return "", fmt.Errorf("resolve workspace root: %w", err)
	}
	info, err := os.Lstat(absolute)
	if err != nil {
		return "", fmt.Errorf("inspect workspace root: %w", err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return "", fmt.Errorf("workspace root %q is not a real directory", absolute)
	}
	return absolute, nil
}

func readModulePath(name string) (string, error) {
	content, err := os.ReadFile(name) // #nosec G304 -- caller derives name from a validated root and catalog-safe directory.
	if err != nil {
		return "", err
	}
	scanner := bufio.NewScanner(bytes.NewReader(content))
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) == 2 && fields[0] == "module" {
			return fields[1], nil
		}
	}
	if err := scanner.Err(); err != nil {
		return "", err
	}
	return "", errors.New("go.mod has no module directive")
}

func applyFile(
	root string,
	name string,
	content []byte,
	owned func([]byte) bool,
	check bool,
) error {
	path := filepath.Join(root, name)
	current, err := os.ReadFile(path) // #nosec G304 -- path is one fixed generated filename under a validated root.
	switch {
	case err == nil:
		if bytes.Equal(current, content) {
			return nil
		}
		if !owned(current) {
			return fmt.Errorf("%w: %s", ErrUnowned, path)
		}
		if check {
			return fmt.Errorf("%w: %s", ErrStale, path)
		}
	case errors.Is(err, os.ErrNotExist):
		if check {
			return fmt.Errorf("%w: %s is missing", ErrStale, path)
		}
	default:
		return fmt.Errorf("read workspace file %s: %w", path, err)
	}
	if err := os.WriteFile(path, content, 0o600); err != nil { // #nosec G306 -- generated workspace files intentionally use owner-only permissions.
		return fmt.Errorf("write workspace file %s: %w", path, err)
	}
	return nil
}

func ownsGoWork(content []byte) bool {
	return bytes.HasPrefix(content, []byte(goWorkMarker+"\n"))
}

func ownsEditor(content []byte) bool {
	var workspace editorWorkspace
	return json.Unmarshal(content, &workspace) == nil && workspace.SpiceGenerated
}
